import java.math.*;
public class P {
  static MathContext MC = new MathContext(34, RoundingMode.HALF_EVEN);
  static BigDecimal c(BigDecimal x){ return x.setScale(2, RoundingMode.HALF_EVEN); }
  public static void main(String[] a){
    BigDecimal i = new BigDecimal("0.0199");
    int[][] casos = {{606,12},{0,0}};
    for (String[] cs : new String[][]{{"606.00","12"},{"431.45","6"}}) {
      BigDecimal total = new BigDecimal(cs[0]); int n = Integer.parseInt(cs[1]);
      BigDecimal p = BigDecimal.ONE.add(i).pow(n, MC);
      BigDecimal d = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(p, MC));
      BigDecimal par = c(total.multiply(i).divide(d, MC));
      BigDecimal tf = c(par.multiply(BigDecimal.valueOf(n)));
      System.out.println(total+" x"+n+" parcela="+par+" total="+tf+" ajuste="+c(tf.subtract(total)));
    }
  }
}
